function readStored() {
  try { return window.localStorage.getItem(STORAGE_KEY) || null } catch { return null }
}
function writeStored(id) {
  try {
    if (id === null) window.localStorage.removeItem(STORAGE_KEY)
    else window.localStorage.setItem(STORAGE_KEY, id)
  } catch { /* private mode etc. */ }
}
const ZOOM_KEY = 'dsh-mywork-shell:zoom'
const ZOOM_MIN = 80; const ZOOM_MAX = 150
function readZoom() { try { const n = Number(window.localStorage.getItem(ZOOM_KEY)); return n >= ZOOM_MIN && n <= ZOOM_MAX ? n : 100 } catch { return 100 } }
function writeZoom(n) { try { if (n === 100) window.localStorage.removeItem(ZOOM_KEY); else window.localStorage.setItem(ZOOM_KEY, String(n)) } catch { /* ignore */ } }
function applyZoom(n) {
  const root = document.documentElement
  root.style.removeProperty('zoom') // older versions zoomed <html> directly
  if (n === 100) root.style.removeProperty('--mywork-zoom')
  else root.style.setProperty('--mywork-zoom', String(n / 100))
}
function familyById(id) {
  return FAMILIES.find((x) => x.id === id) || null
}
function injectStyles() {
  const el = document.createElement('style')
  el.setAttribute('data-plugin', PLUGIN)
  el.textContent = CSS + '\n' + paletteCss()
  document.head.appendChild(el)
  return () => { el.remove() }
}
function currentLang(ctx) {
  try {
    const snap = ctx.locale.getSnapshot()
    if (snap && typeof snap.active === 'string') return snap.active.toLowerCase().startsWith('zh') ? 'zh' : 'en'
  } catch { /* fall through */ }
  const nav = (typeof navigator !== 'undefined' && navigator.language) || 'en'
  return nav.toLowerCase().startsWith('zh') ? 'zh' : 'en'
}

